-- Rebuild Medina Book 4 lesson 14 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 56-60. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '14';
  if existing_count = 4 then
    insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar)
    values ('Мединский курс (Том 4)', '14', '__book4_lesson14_plural__', '', 5, 'rule', '', null);
  elsif existing_count <> 5 then
    raise exception 'Expected 4 legacy or 5 rebuilt Book 4 lesson 14 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'الْحَالُ (обстоятельство состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">الْحَالُ وَصْفٌ فَضْلَةٌ نَكِرَةٌ يُذْكَرُ لِبَيَانِ هَيْئَةِ صَاحِبِهِ. وَالْمُرَادُ بِالْوَصْفِ الْمُشْتَقُّ، كَاسْمِ الْفَاعِلِ، وَاسْمِ الْمَفْعُولِ، وَالصِّفَةِ الْمُشَبَّهَةِ بِاسْمِ الْفَاعِلِ؛ وَالْفَضْلَةُ مَا لَيْسَ رُكْنًا أَسَاسِيًّا فِي الْجُمْلَةِ. وَتُشْتَقُّ الصِّفَةُ الْمُشَبَّهَةُ مِنَ الْفِعْلِ اللَّازِمِ، وَلَهَا أَوْزَانٌ كَثِيرَةٌ.</span><p class="rule-study-text">الْحَالُ — неопределённое производное описание, которое не является обязательной основой предложения и сообщает, в каком состоянии находится связанное с ним слово. В шархе показаны имя действующего, имя страдательного и уподобленное имя прилагательное.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Определение</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">وَصْفٌ مُشْتَقٌّ</span><span class="rule-term-ru">производное описание</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">فَضْلَةٌ</span><span class="rule-term-ru">необязательный член, не являющийся основой предложения</span></div><div class="rule-meaning-card rule-term-object"><span class="rule-term-ar ar-tone-object" dir="rtl" lang="ar">نَكِرَةٌ</span><span class="rule-term-ru">неопределённое слово</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">بَيَانُ هَيْئَةِ صَاحِبِ الْحَالِ</span><span class="rule-term-ru">указание состояния хозяина الْحَالِ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Виды производного описания</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْوَصْفِ</span><span class="rule-table-ru">вид описания</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">имя действующего</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ ضَاحِكًا.</span><span class="rule-table-ru">Студент пришёл смеясь.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ضَاحِكًا</span><span class="rule-table-ru">состояние студента при его приходе</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">اسْمُ الْمَفْعُولِ</span><span class="rule-table-ru">имя страдательного</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">خَرَجَ مُحَمَّدٌ مَسْرُورًا.</span><span class="rule-table-ru">Мухаммад вышел обрадованным.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَسْرُورًا</span><span class="rule-table-ru">состояние Мухаммада при выходе</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الصِّفَةُ الْمُشَبَّهَةُ بِاسْمِ الْفَاعِلِ</span><span class="rule-table-ru">уподобленное имя прилагательное</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ يُونُسُ حَزِينًا.</span><span class="rule-table-ru">Юнус пришёл печальным.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَزِينًا</span><span class="rule-table-ru">устойчивое качество, образованное от непереходного глагола</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Некоторые модели الصِّفَةُ الْمُشَبَّهَةُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">модель</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعِيلٌ</span><span class="rule-table-ru">модель فَعِيلٌ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">حَزِينٌ</span><span class="rule-table-ru">печальный</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مِنْ فِعْلٍ لَازِمٍ</span><span class="rule-table-ru">от непереходного глагола</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعِلٌ</span><span class="rule-table-ru">модель فَعِلٌ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">فَرِحٌ</span><span class="rule-table-ru">радостный</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مِنْ فِعْلٍ لَازِمٍ</span><span class="rule-table-ru">от непереходного глагола</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فُعَالٌ</span><span class="rule-table-ru">модель فُعَالٌ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">شُجَاعٌ</span><span class="rule-table-ru">храбрый</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مِنْ فِعْلٍ لَازِمٍ</span><span class="rule-table-ru">от непереходного глагола</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعْلٌ</span><span class="rule-table-ru">модель فَعْلٌ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ضَخْمٌ</span><span class="rule-table-ru">огромный</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مِنْ فِعْلٍ لَازِمٍ</span><span class="rule-table-ru">от непереходного глагола</span></td></tr></tbody></table></div></div></div>', 'الْحَالُ — неопределённое производное описание, которое не является обязательной основой предложения и сообщает, в каком состоянии находится связанное с ним слово. В шархе показаны имя действующего, имя страдательного и уподобленное имя прилагательное.', 'الْحَالُ وَصْفٌ فَضْلَةٌ نَكِرَةٌ يُذْكَرُ لِبَيَانِ هَيْئَةِ صَاحِبِهِ. وَالْمُرَادُ بِالْوَصْفِ الْمُشْتَقُّ، كَاسْمِ الْفَاعِلِ، وَاسْمِ الْمَفْعُولِ، وَالصِّفَةِ الْمُشَبَّهَةِ بِاسْمِ الْفَاعِلِ؛ وَالْفَضْلَةُ مَا لَيْسَ رُكْنًا أَسَاسِيًّا فِي الْجُمْلَةِ. وَتُشْتَقُّ الصِّفَةُ الْمُشَبَّهَةُ مِنَ الْفِعْلِ اللَّازِمِ، وَلَهَا أَوْزَانٌ كَثِيرَةٌ.'),
    (2, 'صَاحِبُ الْحَالِ (слово, состояние которого раскрывает الْحَالُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-subject" dir="rtl" lang="ar">صَاحِبُ الْحَالِ هُوَ مَا تُبَيِّنُ الْحَالُ هَيْئَتَهُ، وَقَدْ يَكُونُ فَاعِلًا، أَوْ مَفْعُولًا بِهِ، أَوْ كِلَيْهِمَا مَعًا، أَوْ نَائِبَ فَاعِلٍ، أَوْ مُبْتَدَأً، أَوْ خَبَرًا، أَوْ مَجْرُورًا، أَوْ مُضَافًا إِلَيْهِ. وَالْأَصْلُ فِيهِ أَنْ يَكُونَ مَعْرِفَةً، وَيَجُوزُ أَنْ يَكُونَ نَكِرَةً بِمُسَوِّغٍ؛ وَقَدْ يَأْتِي نَكِرَةً بِلَا مُسَوِّغٍ.</span><p class="rule-study-text">صَاحِبُ الْحَالِ — слово, состояние которого поясняет الْحَالُ. Шарх перечисляет восемь возможных синтаксических ролей и условия, при которых обычно определённый хозяин состояния может быть неопределённым.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Восемь возможных ролей</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مَوْقِعُ صَاحِبِ الْحَالِ</span><span class="rule-table-ru">синтаксическая роль</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-table-ru">субъект</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ ضَاحِكًا؛ نَامَ الطِّفْلُ بَاكِيًا.</span><span class="rule-table-ru">Студент пришёл смеясь; ребёнок уснул плача.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبُ، الطِّفْلُ</span><span class="rule-table-ru">хозяева состояния являются субъектами</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أَكَلْتُ اللَّحْمَ مَشْوِيًّا؛ رَأَيْتُ الْهِلَالَ طَالِعًا.</span><span class="rule-table-ru">Я ел мясо жареным; увидел восходящий полумесяц.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">اللَّحْمَ، الْهِلَالَ</span><span class="rule-table-ru">хозяева состояния являются прямыми дополнениями</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَاعِلٌ وَمَفْعُولٌ بِهِ مَعًا</span><span class="rule-table-ru">субъект и дополнение вместе</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">كَلَّمْتُ الْمُدِيرَ مَاشِيَيْنِ؛ اِسْتَقْبَلْتُ أَبِي مُبْتَسِمَيْنِ.</span><span class="rule-table-ru">Я разговаривал с директором, когда мы оба шли; встретил отца, когда мы оба улыбались.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مَاشِيَيْنِ، مُبْتَسِمَيْنِ</span><span class="rule-table-ru">двойственное число охватывает обоих участников</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نَائِبُ فَاعِلٍ</span><span class="rule-table-ru">заместитель субъекта</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">أُكِلَ اللَّحْمُ مَشْوِيًّا؛ طُبِعَ الْكِتَابُ مُجَلَّدًا.</span><span class="rule-table-ru">Мясо было съедено жареным; книга была напечатана переплетённой.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اللَّحْمُ، الْكِتَابُ</span><span class="rule-table-ru">хозяева состояния стоят при страдательном глаголе</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">подлежащее именного предложения</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">دَخَلْتُ عَلَى الْمُدِيرِ وَعِنْدَهُ مُدَرِّسُنَا جَالِسًا؛ الْفَاكِهَةُ نَاضِجَةً مُفِيدَةٌ.</span><span class="rule-table-ru">Я вошёл к директору, когда наш учитель сидел у него; спелый плод полезен.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُدَرِّسُنَا، الْفَاكِهَةُ</span><span class="rule-table-ru">хозяева состояния являются подлежащими</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-table-ru">сказуемое именного предложения</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">هَذَا مُدَرِّسُنَا قَادِمًا؛ هَذَا الْهِلَالُ طَالِعًا.</span><span class="rule-table-ru">Это наш учитель, идущий сюда; это восходящий полумесяц.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">مُدَرِّسُنَا، الْهِلَالُ</span><span class="rule-table-ru">хозяева состояния выступают сказуемыми</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَجْرُورٌ بِحَرْفِ جَرٍّ</span><span class="rule-table-ru">имя после предлога</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَرَرْتُ بِهِنْدٍ جَالِسَةً؛ كَتَبْتُ بِالْقَلَمِ مَكْسُورًا.</span><span class="rule-table-ru">Я прошёл мимо сидящей Хинд; писал сломанной ручкой.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">بِهِنْدٍ، بِالْقَلَمِ</span><span class="rule-table-ru">хозяева состояния находятся после предлога</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru">второй член идафы</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">يُعْجِبُنِي تَأْدِيبُ الْغُلَامِ مُذْنِبًا.</span><span class="rule-table-ru">Мне нравится воспитывать мальчика, когда он провинился.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْغُلَامِ</span><span class="rule-table-ru">хозяин состояния является вторым членом идафы</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример с مُضَافٌ إِلَيْهِ</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗا﴾</span><span class="rule-example-ru">Следуй религии Ибрахима, который был единобожником: إِبْرَاهِيمَ — второй член идафы и хозяин состояния حَنِيفًا.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Когда хозяин состояния может быть неопределённым</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُسَوِّغُ</span><span class="rule-table-ru">условие допустимости</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">تَقَدُّمُ الْحَالِ عَلَى صَاحِبِهَا</span><span class="rule-table-ru">الْحَالُ стоит раньше хозяина</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَنِي سَائِلًا طَالِبٌ.</span><span class="rule-table-ru">Ко мне пришёл спрашивающий студент.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">طَالِبٌ نَكِرَةٌ</span><span class="rule-table-ru">неопределённый хозяин состояния разрешён из-за перестановки</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَخْصِيصُهُ بِوَصْفٍ أَوْ إِضَافَةٍ</span><span class="rule-table-ru">уточнение определением или идафой</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَنِي طَالِبٌ مُجْتَهِدٌ سَائِلًا؛ جَاءَنِي طَالِبُ عِلْمٍ سَائِلًا.</span><span class="rule-table-ru">Ко мне пришёл спрашивающий прилежный студент; ко мне пришёл спрашивающий искатель знания.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">وَصْفٌ أَوْ إِضَافَةٌ</span><span class="rule-table-ru">неопределённое слово получает уточнение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">تَقَدُّمُ نَفْيٍ أَوْ نَهْيٍ أَوِ اسْتِفْهَامٍ</span><span class="rule-table-ru">перед ним отрицание, запрет или вопрос</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">مَا جَاءَ طَالِبٌ مُتَأَخِّرًا؛ لَا يَدْخُلْ طَالِبٌ الْفَصْلَ مُتَأَخِّرًا؛ هَلْ جَاءَ طَالِبٌ مُتَأَخِّرًا؟</span><span class="rule-table-ru">Ни один студент не пришёл поздно; пусть ни один студент не входит в класс с опозданием; пришёл ли какой-нибудь студент поздно?</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">نَفْيٌ، نَهْيٌ، اسْتِفْهَامٌ</span><span class="rule-table-ru">три названных в шархе контекста</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">جُمْلَةٌ مَسْبُوقَةٌ بِوَاوِ الْحَالِ</span><span class="rule-table-ru">الْحَالُ — предложение с وَاوُ الْحَالِ</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَنِي طَالِبٌ وَهُوَ مُبْتَسِمٌ.</span><span class="rule-table-ru">Ко мне пришёл студент, улыбаясь.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">وَهُوَ مُبْتَسِمٌ</span><span class="rule-table-ru">предложение состояния связано союзом و</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример с وَاوُ الْحَالِ</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا﴾</span><span class="rule-example-ru">Или подобно тому, кто проходил мимо селения, когда оно было разрушено до оснований: وَهِيَ خَاوِيَةٌ — предложение состояния.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Неопределённый хозяин без названного условия</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">صَلَّى رَسُولُ اللَّهِ ﷺ قَاعِدًا، وَصَلَّى وَرَاءَهُ رِجَالٌ قِيَامًا.</span><span class="rule-example-ru">Посланник Аллаха ﷺ совершал молитву сидя, а позади него мужчины молились стоя.</span></div></div></div></div>', 'صَاحِبُ الْحَالِ — слово, состояние которого поясняет الْحَالُ. Шарх перечисляет восемь возможных синтаксических ролей и условия, при которых обычно определённый хозяин состояния может быть неопределённым.', 'صَاحِبُ الْحَالِ هُوَ مَا تُبَيِّنُ الْحَالُ هَيْئَتَهُ، وَقَدْ يَكُونُ فَاعِلًا، أَوْ مَفْعُولًا بِهِ، أَوْ كِلَيْهِمَا مَعًا، أَوْ نَائِبَ فَاعِلٍ، أَوْ مُبْتَدَأً، أَوْ خَبَرًا، أَوْ مَجْرُورًا، أَوْ مُضَافًا إِلَيْهِ. وَالْأَصْلُ فِيهِ أَنْ يَكُونَ مَعْرِفَةً، وَيَجُوزُ أَنْ يَكُونَ نَكِرَةً بِمُسَوِّغٍ؛ وَقَدْ يَأْتِي نَكِرَةً بِلَا مُسَوِّغٍ.'),
    (3, 'أَنْوَاعُ الْحَالِ (виды обстоятельства состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-object" dir="rtl" lang="ar">الْحَالُ ثَلَاثَةُ أَنْوَاعٍ: مُفْرَدَةٌ، وَجُمْلَةٌ اسْمِيَّةٌ أَوْ فِعْلِيَّةٌ، وَشِبْهُ جُمْلَةٍ مِنْ جَارٍّ وَمَجْرُورٍ أَوْ ظَرْفٍ. وَالْحَالُ الْمُفْرَدَةُ مَنْصُوبَةٌ، أَمَّا الْجُمْلَةُ وَشِبْهُ الْجُمْلَةِ فَيَكُونُ كُلٌّ مِنْهُمَا فِي مَحَلِّ نَصْبٍ، وَيُعْرَبُ حَالًا.</span><p class="rule-study-text">Шарх делит الْحَالُ на отдельное слово, предложение и شِبْهُ الْجُمْلَةِ. Отдельное слово получает видимый показатель винительного падежа, а предложение и شِبْهُ الْجُمْلَةِ целиком занимают позицию الْحَالِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">الْحَالُ الْمُفْرَدَةُ — отдельное слово</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">عَلَامَةُ النَّصْبِ</span><span class="rule-table-ru">показатель винительного</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُفْرَدُ</span><span class="rule-table-ru">единственное число</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ مَسْرُورًا.</span><span class="rule-table-ru">Студент пришёл радостным.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْفَتْحَةُ</span><span class="rule-table-ru">фатха</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمُثَنَّى</span><span class="rule-table-ru">двойственное число</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبَانِ مَسْرُورَيْنِ.</span><span class="rule-table-ru">Два студента пришли радостными.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">буква ي</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَمْعُ الْمُذَكَّرِ السَّالِمُ</span><span class="rule-table-ru">правильное множественное мужского рода</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطُّلَّابُ مَسْرُورِينَ.</span><span class="rule-table-ru">Студенты пришли радостными.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْيَاءُ</span><span class="rule-table-ru">буква ي</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَمْعُ الْمُؤَنَّثِ السَّالِمُ</span><span class="rule-table-ru">правильное множественное женского рода</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَتِ الطَّالِبَاتُ مَسْرُورَاتٍ.</span><span class="rule-table-ru">Студентки пришли радостными.</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْكَسْرَةُ</span><span class="rule-table-ru">касра вместо фатхи</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">الْحَالُ الْجُمْلَةُ — предложение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَوْعُ الْجُمْلَةِ</span><span class="rule-table-ru">тип предложения</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْأَمْثِلَةُ</span><span class="rule-table-ru">примеры</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">جُمْلَةٌ اسْمِيَّةٌ</span><span class="rule-table-ru">именное предложение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَهُوَ يَضْحَكُ؛ جَاءَ الطَّالِبُ كِتَابُهُ فِي يَدِهِ.</span><span class="rule-table-ru">Студент пришёл смеясь; студент пришёл с книгой в руке.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">هَاتَانِ جُمْلَتَانِ اسْمِيَّتَانِ تَقَعَانِ حَالًا فِي مَحَلِّ نَصْبٍ.</span><span class="rule-table-ru">Оба именных предложения занимают позицию الْحَالِ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جُمْلَةٌ فِعْلِيَّةٌ</span><span class="rule-table-ru">глагольное предложение</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ يَضْحَكُ؛ دَخَلَ الطَّالِبُ وَقَدْ شُرِحَ الدَّرْسُ.</span><span class="rule-table-ru">Студент пришёл смеясь; студент вошёл после того, как урок был объяснён.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">هَاتَانِ جُمْلَتَانِ فِعْلِيَّتَانِ تَقَعَانِ حَالًا فِي مَحَلِّ نَصْبٍ.</span><span class="rule-table-ru">Оба глагольных предложения занимают позицию الْحَالِ.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">شِبْهُ الْجُمْلَةِ — обороты, подобные предложению</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْإِعْرَابُ</span><span class="rule-table-ru">разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">جَارٌّ وَمَجْرُورٌ</span><span class="rule-table-ru">предлог с именем</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">رَأَيْتُ الْعُصْفُورَ عَلَى الْغُصْنِ.</span><span class="rule-table-ru">Я увидел воробья на ветке.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">عَلَى الْغُصْنِ: شِبْهُ جُمْلَةٍ يَقَعُ حَالًا فِي مَحَلِّ نَصْبٍ.</span><span class="rule-table-ru">Оборот عَلَى الْغُصْنِ занимает позицию الْحَالِ.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ظَرْفٌ</span><span class="rule-table-ru">обстоятельственное имя</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">رَأَيْتُ الْقَائِدَ بَيْنَ جُنُودِهِ؛ نَظَرْتُ إِلَى الْعُصْفُورِ فَوْقَ الشَّجَرَةِ.</span><span class="rule-table-ru">Я увидел командира среди его солдат; посмотрел на воробья над деревом.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَيْنَ جُنُودِهِ وَفَوْقَ الشَّجَرَةِ شِبْهَا جُمْلَةٍ يَقَعَانِ حَالًا فِي مَحَلِّ نَصْبٍ.</span><span class="rule-table-ru">Оба обстоятельственных оборота занимают позицию الْحَالِ.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример شِبْهِ الْجُمْلَةِ</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦ﴾</span><span class="rule-example-ru">И он вышел к своему народу в своих украшениях: فِي زِينَتِهِ — شِبْهُ الْجُمْلَةِ в позиции الْحَالِ.</span></div></div></div></div>', 'Шарх делит الْحَالُ на отдельное слово, предложение и شِبْهُ الْجُمْلَةِ. Отдельное слово получает видимый показатель винительного падежа, а предложение и شِبْهُ الْجُمْلَةِ целиком занимают позицию الْحَالِ.', 'الْحَالُ ثَلَاثَةُ أَنْوَاعٍ: مُفْرَدَةٌ، وَجُمْلَةٌ اسْمِيَّةٌ أَوْ فِعْلِيَّةٌ، وَشِبْهُ جُمْلَةٍ مِنْ جَارٍّ وَمَجْرُورٍ أَوْ ظَرْفٍ. وَالْحَالُ الْمُفْرَدَةُ مَنْصُوبَةٌ، أَمَّا الْجُمْلَةُ وَشِبْهُ الْجُمْلَةِ فَيَكُونُ كُلٌّ مِنْهُمَا فِي مَحَلِّ نَصْبٍ، وَيُعْرَبُ حَالًا.'),
    (4, 'الرَّابِطُ فِي جُمْلَةِ الْحَالِ (связка в предложении состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">يُشْتَرَطُ فِي الْحَالِ الَّتِي تَكُونُ جُمْلَةً أَنْ تَشْتَمِلَ عَلَى رَابِطٍ يَعُودُ إِلَى صَاحِبِ الْحَالِ. وَالرَّابِطُ ثَلَاثَةُ أَنْوَاعٍ: الضَّمِيرُ وَحْدَهُ، وَوَاوُ الْحَالِ وَحْدَهَا، وَالْوَاوُ وَالضَّمِيرُ مَعًا.</span><p class="rule-study-text">Если الْحَالُ выражен предложением, внутри него должна быть связь с хозяином состояния. Шарх называет три варианта: только местоимение, только وَاوُ الْحَالِ или وَاوُ الْحَالِ вместе с местоимением.</p></div><div class="rule-study-card"><span class="rule-card-kicker">الضَّمِيرُ وَحْدَهُ — только местоимение</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الرَّابِطُ</span><span class="rule-table-ru">связка</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ يَضْحَكُ.</span><span class="rule-table-ru">Студент пришёл смеясь.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">ضَمِيرٌ مُسْتَتِرٌ تَقْدِيرُهُ هُوَ</span><span class="rule-table-ru">скрытое местоимение هُوَ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَعُودُ إِلَى الطَّالِبِ</span><span class="rule-table-ru">возвращается к слову «студент»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطُّلَّابُ يَضْحَكُونَ.</span><span class="rule-table-ru">Студенты пришли смеясь.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">وَاوُ الْجَمَاعَةِ</span><span class="rule-table-ru">وَاوُ الْجَمَاعَةِ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَعُودُ إِلَى الطُّلَّابِ</span><span class="rule-table-ru">возвращается к слову «студенты»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبَانِ يَضْحَكَانِ.</span><span class="rule-table-ru">Два студента пришли смеясь.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">أَلِفُ الِاثْنَيْنِ</span><span class="rule-table-ru">алиф двойственного числа</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَعُودُ إِلَى الطَّالِبَيْنِ</span><span class="rule-table-ru">возвращается к двум студентам</span></td></tr><tr><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَتِ الطَّالِبَاتُ يَضْحَكْنَ.</span><span class="rule-table-ru">Студентки пришли смеясь.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">نُونُ النِّسْوَةِ</span><span class="rule-table-ru">نُونُ النِّسْوَةِ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يَعُودُ إِلَى الطَّالِبَاتِ</span><span class="rule-table-ru">возвращается к студенткам</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример местоименной связки</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿وَجَآءُوٓ أَبَاهُمۡ عِشَآءٗ يَبۡكُونَ﴾</span><span class="rule-example-ru">И они пришли к своему отцу вечером, плача: وَاوُ الْجَمَاعَةِ в يَبْكُونَ связывает предложение с субъектом.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">وَاوُ الْحَالِ وَحْدَهَا أَوْ مَعَ الضَّمِيرِ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">نَوْعُ الرَّابِطِ</span><span class="rule-table-ru">тип связки</span></th><th><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْوَاوُ وَحْدَهَا</span><span class="rule-table-ru">только وَاوُ الْحَالِ</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">وَصَلْتُ مَكَّةَ وَالشَّمْسُ تَغْرُبُ؛ وَصَلْتُ مَكَّةَ وَقَدْ غَرَبَتِ الشَّمْسُ.</span><span class="rule-table-ru">Я прибыл в Мекку, когда солнце садилось; я прибыл в Мекку после захода солнца.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَا ضَمِيرَ فِي جُمْلَةِ الْحَالِ</span><span class="rule-table-ru">в предложении состояния нет возвращающегося местоимения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْوَاوُ وَالضَّمِيرُ مَعًا</span><span class="rule-table-ru">وَاوُ الْحَالِ и местоимение вместе</span></td><td><span class="rule-table-ar ar-tone-object" dir="rtl" lang="ar">جَاءَ الطَّالِبُ وَهُوَ يَضْحَكُ؛ حَجَجْتُ وَأَنَا صَغِيرٌ.</span><span class="rule-table-ru">Студент пришёл смеясь; я совершил хадж, когда был маленьким.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هُوَ، أَنَا</span><span class="rule-table-ru">явные местоимения возвращаются к хозяину состояния</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример وَاوُ الْحَالِ и местоимения</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ﴾</span><span class="rule-example-ru">Не приближайтесь к молитве, будучи пьяными: в وَأَنْتُمْ соединены وَاوُ الْحَالِ и местоимение أَنْتُمْ.</span></div></div></div></div>', 'Если الْحَالُ выражен предложением, внутри него должна быть связь с хозяином состояния. Шарх называет три варианта: только местоимение, только وَاوُ الْحَالِ или وَاوُ الْحَالِ вместе с местоимением.', 'يُشْتَرَطُ فِي الْحَالِ الَّتِي تَكُونُ جُمْلَةً أَنْ تَشْتَمِلَ عَلَى رَابِطٍ يَعُودُ إِلَى صَاحِبِ الْحَالِ. وَالرَّابِطُ ثَلَاثَةُ أَنْوَاعٍ: الضَّمِيرُ وَحْدَهُ، وَوَاوُ الْحَالِ وَحْدَهَا، وَالْوَاوُ وَالضَّمِيرُ مَعًا.'),
    (5, 'الْجَمْعُ عَلَى فِعَالٍ وَفُعُولٍ (множественное число по моделям فِعَالٌ и فُعُولٌ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">تُسْتَعْمَلُ جُمُوعُ فِعَالٍ وَفُعُولٍ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ؛ فَقِيَامٌ جَمْعُ قَائِمٍ وَقَائِمَةٍ، وَقُعُودٌ جَمْعُ قَاعِدٍ وَقَاعِدَةٍ، وَجُلُوسٌ جَمْعُ جَالِسٍ وَجَالِسَةٍ.</span><p class="rule-study-text">Формы множественного числа قِيَامٌ, قُعُودٌ и جُلُوسٌ употребляются и для мужского, и для женского рода. Шарх приводит для каждой формы соответствующие слова единственного числа.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Единственное и множественное число</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْجَمْعُ</span><span class="rule-table-ru">множественное</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُفْرَدُ الْمُذَكَّرُ</span><span class="rule-table-ru">мужской род</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">الْمُفْرَدُ الْمُؤَنَّثُ</span><span class="rule-table-ru">женский род</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское значение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قِيَامٌ</span><span class="rule-table-ru">множественное по модели فِعَالٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">قَائِمٌ</span><span class="rule-table-ru">стоящий</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">قَائِمَةٌ</span><span class="rule-table-ru">стоящая</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لِلْمُذَكَّرِ وَالْمُؤَنَّثِ</span><span class="rule-table-ru">стоящие мужчины или женщины</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">قُعُودٌ</span><span class="rule-table-ru">множественное по модели فُعُولٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">قَاعِدٌ</span><span class="rule-table-ru">сидящий</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">قَاعِدَةٌ</span><span class="rule-table-ru">сидящая</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لِلْمُذَكَّرِ وَالْمُؤَنَّثِ</span><span class="rule-table-ru">сидящие мужчины или женщины</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُلُوسٌ</span><span class="rule-table-ru">множественное по модели فُعُولٌ</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">جَالِسٌ</span><span class="rule-table-ru">сидящий</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">جَالِسَةٌ</span><span class="rule-table-ru">сидящая</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لِلْمُذَكَّرِ وَالْمُؤَنَّثِ</span><span class="rule-table-ru">сидящие мужчины или женщины</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример</span><div class="rule-example-list"><div class="rule-example-card rule-term-quran"><span class="rule-example-ar ar-tone-quran rule-quran-ar" dir="rtl" lang="ar">﴿ٱلَّذِينَ يَذۡكُرُونَ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِهِمۡ﴾</span><span class="rule-example-ru">Которые поминают Аллаха стоя, сидя и лёжа на боках: قِيَامًا и قُعُودًا — формы множественного числа.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пример из хадиса</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">خَرَجَ رَسُولُ اللَّهِ ﷺ فَإِذَا نِسْوَةٌ جُلُوسٌ.</span><span class="rule-example-ru">Посланник Аллаха ﷺ вышел — и оказалось, что женщины сидят.</span></div></div></div></div>', 'Формы множественного числа قِيَامٌ, قُعُودٌ и جُلُوسٌ употребляются и для мужского, и для женского рода. Шарх приводит для каждой формы соответствующие слова единственного числа.', 'تُسْتَعْمَلُ جُمُوعُ فِعَالٍ وَفُعُولٍ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ؛ فَقِيَامٌ جَمْعُ قَائِمٍ وَقَائِمَةٍ، وَقُعُودٌ جَمْعُ قَاعِدٍ وَقَاعِدَةٍ، وَجُلُوسٌ جَمْعُ جَالِسٍ وَجَالِسَةٍ.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '14'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '14'
);

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الدَّرْسُ الرَّابِعَ عَشَرَ
الْحَالُ
الحالُ : وَصْفٌ فَضْلَة نكرة ، يُذْكَرُ لِبَيَانِ هَيْئَةِ صَاحِبِهِ .
والمرادُ بالوصفِ : الْمُشْتَقُّ ، نحو :
1- اسم الفاعل : جاء الطالب ضاحكاً .
2- اسم المفعول : خرج محمد مسروراً .
3- الصَّفَةُ الْمُشَبَّهَةُ ( أي : الْمُشَبَّهَة باسم الفاعل ) : جاءَ يونسُ حزيناً .
وتُشْتَقُّ من الفعل اللاَّزِم . وأوزانها كثيرة منها : فَعِيلٌ (حَزِينٌ ) وفَعِلٌ ( فَرِحٌ )
وفُعَالٌ ( شُجَاعٌ ) وفَعْلٌ ( ضَخْمٌ ) .
والمرادُ بالفَضْلَةِ : ما ليسَ رُكْناً أَسَاسِيّاً في الجملة .', 56, 57, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '14' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'صَاحِبُ الحالِ
الحالُ تُبَيِّنُ هيئةَ صاحبِها , وصاحبُ الحالِ يكونُ :
1- فاعلا , نحو : جاء الطالبُ ضاحكاً . نَامَ الطفلُ بَاكِياً .
2- مفعولا به , نحو : أكلت اللَّحْمَ مَشْوِيّاً . رأيتُ الهلالَ طَالِعاً .
3- فاعلا ومفعولا به معاً , نحو : كلَّمْتُ المديرَ مَاشِيَيْنِ . اِسْتَقْبَلْتُ أَبِي مُبْتَسِمَيْنِ
4- نائبَ فاعلٍ , نحو : أُكِلَ اللَّحْمُ مَشْوِيّاً . طُبِعَ الكتابُ مُجَلَّداً .
5- مبتدأ , نحو : دخلتُ على المدير وعنده مدرسُنا جالساً . الفَاكِهَةُ نَاضِجَةً مُفِيدَةٌ .
6- خبرا , نحو : هذا مدرسُنا قادماً . هذا الهلالُ طَالِعاً .
7- جارًّا ومجروراً , نحو : مررت بهندٍ جالسةً . كتبتُ بالقلمِ مكسوراً .
8- مضافا إليه , نحو : يُعْجِبُنِي تَأْدِيبُ الغُلاَمِ مُذْنِباً ، ونحو قوله تعالى :
﴿ أَنِ اتَّبِعْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا ﴾ .
الأصل في صاحب الحال أن يكون معرفة , وقد يأتي نكرة بأحد الْمُسَوَّغَاتِ الآتية :
1- إذا تقدَّمتِ الحالُ على صاحبِها , نحو : جاءني سائلاً طالبٌ .
2- إذا خُصِّصَ صاحبُ الحالِ بوصفٍ ، أو إضافةٍ , نحو :
أ- جاءني طالبٌ مجتهدٌ سائلاً ( وصف ) .
ب- جاءني طالبُ علمٍ سائلاً ( إضافة ) .
3- إذا تقدَّمَ على صاحبِ الحالِ نَهْيٌ ، أو نَفْيٌ ، أو استفهامٌ , نحو :
- ما جاء طالبٌ مُتَأَخِّراً ( نفي ) .
- لا يدخلْ طالبٌ الفصلَ مُتَأَخِّراً ( نهي ) .
- هل جاء طالبٌ مُتَأَخِّراً ؟ ( استفهام ) .
4- إذا كانَ الحالُ جملةً مسبوقةً بالواوِ , نحو : جاءني طالبٌ وهو مبتسمٌ .
ومنه قوله تعالى : ﴿ أَوْ كَالَّذِي مَرَّ عَلَى قَرْيَةٍ وَهِيَ خَاوِيَةٌ عَلَى عُرُوشِهَا ﴾ .
قد يأتي صاحب الحال نكرة بلا مُسَوِّغٍ , كما في الحديث : " صلَّى رسولُ اللهِ ﷺ قاعداً وصَلَّى وَرَاءَهُ رِجَالٌ قِيَاماً ".', 57, 58, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '14' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'أنواعُ الحالِ
1- الحالُ الْمُفْرَدَةُ ( أي : ما ليس بجملة ) نحو : جاء الطَّالبُ مَسْرُوراً ,
جاء الطَّالبان مَسْرُورَيْنِ , جاء الطُّلابُ مَسْرُورِيْنَ , جاءت الطَّالباتُ مَسْرُورَاتٍ .
مسروراً : حال منصوب وعلامة نصبه الفتحة .
مسرورين : حال منصوب وعلامة نصبه الياء .
مسروراتٍ : حال منصوب وعلامة نصبه الكسرة .
2- الحالُ الجملةُ , والجملة نوعان :
أ- اِسْمِيَّةٌ , نحو : جاء الطالبُ وهو يضحكُ . جاء الطالبُ كِتَابُهُ في يَدِهِ .
• الجملة الاسمية ( هو يضحك ، كتابه في يده ) في محل نصب حال .
ب- فِعْلِيَّةٌ , نحو : جاء الطالبُ يضحكُ . دخل الطالبُ وقد شُرِحَ الدرسُ .
• الجملة الفعلية ( يضحك ، شُرِحَ الدرسُ ) في محل نصب حال .
3- شِبْهُ الجملةِ ، وهي نوعان :
أ- جَارٌّ ومَجْرُورٌ , نحو : رأيتُ العُصْفُورَ عَلَى الْغُصْنِ . ومنه قوله تعالى :
﴿ فَخَرَجَ عَلَى قَوْمِهِ فِي زِينَتِهِ ﴾ .
ب- ظَرْفٌ , نحو : رأيتُ القَائِدَ بَيْنَ جُنُودِهِ . نظرتُ إلى العصفور فوقَ الشَّجرةِ .
شبه الجملة ( الجار والمجرور , والظَّرف ) في محل نصب حال .', 58, 59, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '14' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الرَّابِطُ
يُشترط في الحال الجملة أن تشتمل على رابط يعود إلى صاحب الحال , والرَّابط ثلاثة أنواع :
1- الضَّميرُ وحدَه , نحو : جاءَ الطَّالبُ يضحكُ , الرابط : ضمير مستتر تقديره : هو .
ونحو : جاءَ الطُّلابُ يضحكون ، الرابط : واو الجماعة .
ونحو : جاءَ الطَّالبانِ يضحكان ، الرابط ألف الاثنين .
ونحو : جاءتِ الطَّالباتُ يضحكْنَ ، الرابط نون النِّسوة .
ومنه قوله تعالى : ﴿ وَجَاءُوا أَبَاهُمْ عِشَاءً يَبْكُونَ ﴾ الرابط : واو الجماعة .
2- الواوُ وحدَها , نحو : وصلت مكة والشَّمْسُ تَغْرُبُ . وصلتُ مكَّةَ وقد غَرَبَتِ الشَّمسُ .
3- الواوُ والضَّميرُ معاً , نحو : جاء الطالبُ وهو يضحك . حججتُ وأنا صغيرٌ .
ومنه قوله تعالى : ﴿ لَا تَقْرَبُوا الصَّلَاةَ وَأَنْتُمْ سُكَارَى ﴾ .', 59, 59, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '14' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'الجمعُ على فِعَالٍ ، وفُعُولٍ
قال تعالى : ﴿ الَّذِينَ يَذْكُرُونَ اللهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ ... ﴾ .
وفي الحديث : " خَرَجَ رَسُولُ اللهِ ﷺ فَإِذَا نِسْوَةٌ جُلُوسٌ " .
قِيَاماً ، وقُعُوداً ، وجُلُوسٌ : جَمْعٌ لِلْمُذَكَّرِ وَالْمُؤَنَّثِ . فقِيَامٌ جَمْعُ قَائِمٍ ، وقَائِمَةٍ .
وقُعُودٌ : جَمْعُ قَاعِدٍ ، وقَاعِدَةٍ . وجُلُوسٌ : جَمْعُ جَالِسٍ ، وجَالِسَةٍ .', 59, 60, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '14' and sort_order = 5;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '14' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '14';
  if updated_count <> 5 or source_count <> 5 then
    raise exception 'Book 4 lesson 14 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
